import { useState } from 'react';
import {
  JxStepper,
  JxInputField,
  JxTextareaField,
  JxButton,
  JxDivider,
} from '@jinx-ui/react';

interface RegistrationFormProps {
  onSubmit: (data: {
    fullName: string;
    email: string;
    phone: string;
    address: string;
    city: string;
    postalCode: string;
  }) => void;
}

const steps = [{ label: 'Контакты' }, { label: 'Адрес' }, { label: 'Проверка' }];

export default function RegistrationForm({ onSubmit }: RegistrationFormProps) {
  const [step, setStep] = useState(0);
  const [fullName, setFullName] = useState('');
  const [email, setEmail] = useState('');
  const [phone, setPhone] = useState('');
  const [address, setAddress] = useState('');
  const [city, setCity] = useState('');
  const [postalCode, setPostalCode] = useState('');

  const canGoNext = step === 0 ? fullName.trim() !== '' && email.trim() !== '' : true;

  const goNext = () => setStep((current) => Math.min(current + 1, steps.length - 1));
  const goBack = () => setStep((current) => Math.max(current - 1, 0));

  const submit = () => {
    onSubmit({ fullName, email, phone, address, city, postalCode });
  };

  return (
    <div
      style={{
        display: 'flex',
        flexDirection: 'column',
        gap: '20px',
        maxWidth: '480px',
        padding: '24px',
        background: 'var(--jx-surface)',
        border: '1px solid var(--jx-border)',
        borderRadius: 'var(--jx-r-lg)',
      }}
    >
      <JxStepper steps={steps} current={step} />

      {step === 0 && (
        <div style={{ display: 'flex', flexDirection: 'column', gap: '12px' }}>
          <JxInputField
            label="Полное имя"
            required
            value={fullName}
            onChange={(event) => setFullName(event.target.value)}
          />
          <JxInputField
            label="Электронная почта"
            type="email"
            required
            value={email}
            onChange={(event) => setEmail(event.target.value)}
          />
          <JxInputField
            label="Телефон"
            type="tel"
            value={phone}
            onChange={(event) => setPhone(event.target.value)}
          />
        </div>
      )}

      {step === 1 && (
        <div style={{ display: 'flex', flexDirection: 'column', gap: '12px' }}>
          <JxTextareaField
            label="Адрес"
            rows={3}
            value={address}
            onChange={(event) => setAddress(event.target.value)}
          />
          <JxInputField label="Город" value={city} onChange={(event) => setCity(event.target.value)} />
          <JxInputField
            label="Почтовый индекс"
            value={postalCode}
            onChange={(event) => setPostalCode(event.target.value)}
          />
        </div>
      )}

      {step === 2 && (
        <div style={{ display: 'flex', flexDirection: 'column', gap: '4px' }}>
          <span style={{ color: 'var(--jx-text)', fontWeight: 600 }}>Проверьте данные</span>
          <span style={{ color: 'var(--jx-text-2)' }}>Имя: {fullName || '—'}</span>
          <span style={{ color: 'var(--jx-text-2)' }}>Почта: {email || '—'}</span>
          <span style={{ color: 'var(--jx-text-2)' }}>Телефон: {phone || '—'}</span>
          <JxDivider />
          <span style={{ color: 'var(--jx-text-2)' }}>Адрес: {address || '—'}</span>
          <span style={{ color: 'var(--jx-text-2)' }}>Город: {city || '—'}</span>
          <span style={{ color: 'var(--jx-text-2)' }}>Индекс: {postalCode || '—'}</span>
        </div>
      )}

      <div style={{ display: 'flex', justifyContent: 'space-between', gap: '8px' }}>
        <JxButton variant="ghost" onClick={goBack} disabled={step === 0}>
          Назад
        </JxButton>
        {step < steps.length - 1 ? (
          <JxButton variant="primary" onClick={goNext} disabled={!canGoNext}>
            Дальше
          </JxButton>
        ) : (
          <JxButton variant="primary" onClick={submit}>
            Отправить
          </JxButton>
        )}
      </div>
    </div>
  );
}

